-- 通知公告数据
INSERT INTO notice (id, title, content, cover_image, notice_type, publisher_id, publish_time, end_time, status, view_count, create_time, update_time, deleted) VALUES (1,'书魂商城上线公告','<p>亲爱的用户们：</p><p>书魂商城正式上线啦！我们致力于为您提供优质的图书购物体验。</p><p>目前平台已上线数千种图书，涵盖编程技术、文学小说、历史传记、经济管理等多个品类，欢迎选购！</p><p>新用户注册即享优惠券礼包，快来体验吧！</p>','/uploads/2026-05-01/notice1.jpg','平台公告',1,'2026-04-29 17:03:00','2026-06-30 23:59:59',1,5,'2026-04-29 00:00:00','2026-05-02 02:44:17',0),(2,'五一劳动节促销活动','<p><strong>五一劳动节大促！</strong></p><p>为庆祝五一劳动节，书魂商城推出限时优惠活动：</p><ul><li>全场图书8折优惠</li><li>满100减20</li><li>满200减50</li></ul><p>活动时间：5月1日-5月7日</p><p>机会难得，不要错过！</p>',NULL,'活动通知',1,'2026-04-30 00:00:00','2026-05-07 23:59:59',1,3,'2026-04-30 00:00:00','2026-05-02 02:44:17',0),(3,'关于优化搜索功能的通知','<p>尊敬的各位用户：</p><p>为了提升您的购物体验，我们近期对搜索功能进行了全面优化：</p><ul><li>新增分类筛选功能</li><li>优化关键词匹配算法</li><li>支持多条件组合搜索</li><li>新增价格区间筛选</li></ul><p>现在您可以更快速地找到心仪的图书，快去试试吧！</p>',NULL,'功能更新',1,'2026-05-01 00:00:00','2026-06-30 23:59:59',1,2,'2026-05-01 00:00:00','2026-05-02 02:44:17',0),(4,'端午节优惠活动','<p><strong>端午安康！书魂商城送好礼！</strong></p><p>端午节期间，书魂商城推出以下优惠：</p><ul><li>购买任意图书赠送精美书签</li><li>满150元包邮</li><li>部分图书低至6折</li></ul><p>活动时间：6月1日-6月10日</p>',NULL,'活动通知',1,'2026-05-01 00:00:00','2026-06-10 23:59:59',1,1,'2026-05-01 00:00:00','2026-05-02 02:44:17',0),(5,'平台商家入驻指南','<p><strong>欢迎优质商家入驻书魂商城！</strong></p><p>入驻流程：</p><ol><li>点击"商家入驻"提交申请</li><li>填写店铺信息及资质材料</li><li>平台审核（1-3个工作日）</li><li>审核通过后上架商品</li></ol><p>我们提供：</p><ul><li>低门槛入驻</li><li>专业运营支持</li><li>完善的物流体系</li><li>安全保障</li></ul>',NULL,'平台公告',1,'2026-05-02 00:00:00','2026-12-31 23:59:59',1,0,'2026-05-02 00:00:00','2026-05-02 02:44:17',0),(6,'关于订单状态说明','<p><strong>订单状态说明：</strong></p><ul><li><strong>待付款</strong>：订单已提交，请及时完成支付</li><li><strong>待发货</strong>：支付成功，等待商家发货</li><li><strong>待收货</strong>：商品已发出，请留意物流信息</li><li><strong>待评价</strong>：商品已签收，欢迎分享您的购物体验</li><li><strong>已完成</strong>：订单已完成</li><li><strong>已取消</strong>：订单已取消</li><li><strong>退款中</strong>：退款申请已提交</li><li><strong>已退款</strong>：退款已完成</li></ul>',NULL,'功能更新',1,'2026-05-03 00:00:00','2026-12-31 23:59:59',1,0,'2026-05-03 00:00:00','2026-05-03 00:00:00',0),(7,'暑假阅读季活动','<p><strong>暑假阅读季，好书伴你过夏天！</strong></p><p>活动期间：</p><ul><li><strong>中小学生必读书目</strong>专区满100减30</li><li><strong>考研必备教材</strong>8折优惠</li><li><strong>经典文学名著</strong>买二送一</li></ul><p>活动时间：7月1日-8月31日</p>',NULL,'活动通知',1,'2026-05-05 00:00:00','2026-08-31 23:59:59',1,0,'2026-05-05 00:00:00','2026-05-05 00:00:00',0),(8,'支付系统升级通知','<p><strong>支付系统升级维护通知</strong></p><p>为了提供更安全、便捷的支付服务，我们将于本周六凌晨2:00-6:00进行支付系统升级维护。</p><p>维护期间将暂停所有支付功能，给您带来的不便敬请谅解！</p>',NULL,'平台公告',1,'2026-05-06 00:00:00','2026-05-10 23:59:59',1,0,'2026-05-06 00:00:00','2026-05-06 00:00:00',0),(9,'关于新增图书分类的通知','<p><strong>新增图书分类通知</strong></p><p>为了给您提供更精细化的图书分类体验，我们新增了以下分类：</p><ul><li><strong>心理学</strong>（人文社科下）</li><li><strong>平面设计</strong>（艺术设计下）</li></ul><p>欢迎各位读者前往对应分类选购心仪图书！</p>',NULL,'功能更新',1,'2026-05-06 00:00:00','2026-12-31 23:59:59',1,0,'2026-05-06 00:00:00','2026-05-06 00:00:00',0);
SELECT setval('notice_id_seq', (SELECT COALESCE(MAX(id), 0) FROM notice));

